```python
import random
import nltk
from nltk.corpus import wordnet
keywords = ['orange', 'red', 'purple', 'pink', 'clouds', 'sky', 'ocean', 'beach', 'warm', 'peaceful', 'serene']
# Define synonyms for the keywords using WordNet
synonyms = []
for keyword in keywords:
    for syn in wordnet.synsets(keyword):
        for lemma in syn.lemmas():
            synonyms.append(lemma.name())
# Generate a random sentence using the synonyms
sentence = 'The '
if random.random() < 0.5:
    sentence += random.choice(synonyms)
else:
    sentence += 'sun'
sentence += ' sets over the '
if random.random() < 0.5:
    sentence += random.choice(synonyms)
else:
    sentence += 'horizon'
sentence += ', painting the '
if random.random() < 0.5:
