else:
    sentence += 'sky'
sentence += ' with '
if random.random() < 0.5:
    sentence += random.choice(synonyms)
else:
    sentence += 'vibrant colors'
sentence += ' and casting a '
if random.random() < 0.5:
    sentence += random.choice(synonyms)
else:
