// Define a method to compute the correlation between two arrays of data
static double Correlation(double[] x, double[] y)
{
    // Compute the means of the two arrays
    double meanX = x.Average();
    double meanY = y.Average();
    // Compute the standard deviations of the two arrays
    double stdDevX = Math.Sqrt(x.Select(d => Math.Pow(d - meanX, 2)).Average());
    double stdDevY = Math.Sqrt(y.Select(d => Math.Pow(d - meanY, 2)).Average());
    // Compute the covariance between the two arrays
    double covariance = x.Zip(y, (a, b) => (a - meanX) * (b - meanY)).Average();
    // Compute the correlation between the two arrays
    double correlation = covariance / (stdDevX * stdDevY);
    return correlation;
}
