func handleAPICalls(completion: @escaping (Result<[String:Any]>) -> Void) {
    guard let url = URL(string: "https://api.example.com/data") else {
        completion(.failure(.invalidURL))
        return
    }
    let task = URLSession.shared.dataTask(with: url) { (data, response, error) in
        if let error = error {
            completion(.failure(.networkError(error)))
            return
        }
        guard let httpResponse = response as? HTTPURLResponse else {
            completion(.failure(.invalidResponse))
            return
        }
        guard httpResponse.statusCode == 200 else {
            completion(.failure(.invalidStatusCode(httpResponse.statusCode)))
            return
        }
        guard let data = data else {
            completion(.failure(.noData))
            return
        }
        do {
            let json = try JSONSerialization.jsonObject(with: data, options: [])
            guard let jsonDictionary = json as? [String:Any] else {
                completion(.failure(.invalidData))
                return
            }

            let personalData = jsonDictionary["personal_info"] as? [String:Any]
            guard let name = personalData?["name"] as? String else {
                completion(.failure(.missingInfo))
                return
            }

            let age = personalData?["age"] as? Int ?? 0
            let gender = personalData?["gender"] as? String ?? "Unknown"

            if age < 18 {
                completion(.failure(.invalidAge))
                return
            }

            if gender != "Male" && gender != "Female" {
                completion(.failure(.invalidGender))
                return
            }

            if name.count < 3 || name.count > 30 {
                completion(.failure(.invalidNameLength))
                return
            }

            completion(.success(jsonDictionary))
        } catch {
            completion(.failure(.serializationError(error)))
        }
    }
