function generateLine($words, $syllables) {
    shuffle($words);
    $line = "";
    $count = 0;
    foreach ($words as $word) {
        $count += countSyllables($word);
        if ($count <= $syllables) {
            $line .= $word . " ";
        } else {
            break;
        }
    }
    return trim($line);
}
function countSyllables($word) {
    // count the number of vowels in the word
    $vowels = preg_match_all('/[aeiouy]/i', $word);
    // subtract one vowel for every two consecutive vowels
    $vowels -= preg_match_all('/[aeiouy]{2,}/i', $word);
    // add one syllable if the word ends with "e"
    $vowels += preg_match('/e$/', $word);
    // add one syllable if the word ends with a consonant followed by "le"
    $vowels += preg_match('/[^aeiouy]le$/', $word);
    // add one syllable if the word has no vowels but is not a single consonant
    $vowels += preg_match('/^[^aeiouy]{2,}$/', $word);
    return max(1, $vowels);
}
?>
