Here is a sample code using Gensim to perform LDA topic modeling on "The Great Gatsby":
```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using gensim;
using gensim.models.ldamodel;
using gensim.corpora.dictionary;
class Program
{
    static void Main(string[] args)
    {
        string text = System.IO.File.ReadAllText(@"C:\path\to\great_gatsby.txt");
        // Tokenize the text
        var tokenizer = new gensim.utils.SimpleTokenizer();
        var tokens = tokenizer.Tokenize(text);
        // Create a dictionary of the tokens
        var dictionary = new Dictionary(tokens.Select((token, index) => new KeyValuePair<string, int>(token, index)));
        // Create a bag-of-words representation of the tokens
        var corpus = new List<List<(int, int)>>();
        foreach (var group in tokens.GroupBy(token => token))
        {
            var wordIndex = dictionary[group.Key];
            var wordCount = group.Count();
            corpus.Add(new List<(int, int)> { (wordIndex, wordCount) });
        }
        // Train an LDA model on the corpus
        var ldaModel = LdaModel.Train(corpus, numTopics: 10, id2word: dictionary);
        // Print the top words for each topic
        foreach (var topic in ldaModel.ShowTopics(numWords: 10))
        {
            Console.WriteLine($"Topic {topic.Id}: {string.Join(", ", topic.Words.Select(word => dictionary[word.Item1]))}");
        }
    }
}
