    return (strpos($word, "_") === false && strpos($word, "-") === false && (substr($word, -1) == "s" ? in_array(substr($word, 0, -1), array("a", "an", "any", "each", "every", "many", "several", "these", "those")) : in_array($word, array("a", "an", "any", "each", "every", "many", "several", "these", "those", "i", "we", "you", "he", "she", "it", "they")) || preg_match("/^(.*[^s])s$/", $word)));
});
