```Go
package main
import (
    "encoding/json"
    "fmt"
    "log"
    "net/http"
    "github.com/gorilla/mux"
)
type Todo struct {
    ID        string   `json:"id,omitempty"`
    Title     string   `json:"title,omitempty"`
    Completed bool     `json:"completed,omitempty"`
}
var todos []Todo
func GetTodos(w http.ResponseWriter, r *http.Request) {
    json.NewEncoder(w).Encode(todos)
}
func GetTodoById(w http.ResponseWriter, r *http.Request) {
    params := mux.Vars(r)
    for _, item := range todos {
        if item.ID == params["id"] {
            json.NewEncoder(w).Encode(item)
            return
        }
    }
    json.NewEncoder(w).Encode(&Todo{})
}
func CreateTodo(w http.ResponseWriter, r *http.Request) {
    var todo Todo
    _ = json.NewDecoder(r.Body).Decode(&todo)
    todos = append(todos, todo)
    json.NewEncoder(w).Encode(todo)
}
func UpdateTodoById(w http.ResponseWriter, r *http.Request) {
    params := mux.Vars(r)
    for index, item := range todos {
        if item.ID == params["id"] {
            todos[index].Completed = !todos[index].Completed
            json.NewEncoder(w).Encode(todos[index])
            return
        }
    }
    json.NewEncoder(w).Encode(&Todo{})
}
func DeleteTodoById(w http.ResponseWriter, r *http.Request) {
    params := mux.Vars(r)
    for index, item := range todos {
        if item.ID == params["id"] {
            todos = append(todos[:index], todos[index+1:]...)
            break
        }
    }
    json.NewEncoder(w).Encode(todos)
}
func main() {
    router := mux.NewRouter()
    todos = append(todos, Todo{ID: "1", Title: "Task 1", Completed: false})
    todos = append(todos, Todo{ID: "2", Title: "Task 2", Completed: false})
    router.HandleFunc("/todos", GetTodos).Methods("GET")
    router.HandleFunc("/todos/{id}", GetTodoById).Methods("GET")
    router.HandleFunc("/todos", CreateTodo).Methods("POST")
    router.HandleFunc("/todos/{id}", UpdateTodoById).Methods("PUT")
    router.HandleFunc("/todos/{id}", DeleteTodoById).Methods("DELETE")
    fmt.Println("Server started at port 8000")
    log.Fatal(http.ListenAndServe(":8000", router))
}
```
