#include <iostream>
#include <vector>
using namespace std;
double lerp(double x, double x0, double x1, double y0, double y1) {
    return y0 + (y1 - y0) * (x - x0) / (x1 - x0);
}
int main() {
    vector<double> x = {1, 2, 3, 4, 5};
    vector<double> y = {2, 4, 1, 5, 3};
    double xval = 2.5;
