```
#include <iostream>
#include <fftw3.h>
using namespace std;
int main() {
    int N = 8;
    double x[N] = {1, 2, 3, 4, 5, 6, 7, 8};
    fftw_complex y[N];
    fftw_plan plan = fftw_plan_dft_r2c_1d(N, x, y, FFTW_ESTIMATE);
    fftw_execute(plan);
    fftw_destroy_plan(plan);
    for (int i = 0; i < N/2+1; i++) {
